#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/claude/tasks/setup-ai.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Install the Claude Code plugins of the repository, and uninstall the project plugins that left its list"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--upgrade" help="also update the marketplaces and the listed plugins"

import json
import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def text(value):
  """A JSON value as the string interpolation of jq writes it."""
  return value if isinstance(value, str) else json.dumps(value)


def print_errors(err):
  """Each line of err that is not empty, as an error line under the step."""
  for line in err.split("\n"):
    if line:
      helpers.print_error(f"  {line}")


def claude_step(label, *args):
  """One step: `claude` writes its progress to stdout and its errors to stderr.
  The progress is discarded. On a failure, the error goes under the step, and
  the next steps still run: one failed plugin does not block the others.
  Returns True on success."""
  helpers.print_wait(f"{label} ... ")
  result = helpers.tool(
    "claude",
    *args,
    stdin=subprocess.DEVNULL,
    stdout=subprocess.DEVNULL,
    stderr=subprocess.PIPE,
    text=True,
    errors="surrogateescape",
  )
  if result.returncode == 0:
    helpers.print_success()
    return True
  helpers.print_error()
  print_errors(result.stderr.rstrip("\n"))
  return False


def claude_json(*args):
  """The JSON list that `claude <args> --json` writes, or [] when it fails or
  writes no list."""
  result = helpers.tool("claude", *args, stdout=subprocess.PIPE, text=True, errors="surrogateescape")
  try:
    answer = json.loads(result.stdout)
  except ValueError:
    return []
  return answer if isinstance(answer, list) else []


def plugins_here(root):
  """The (plugin, scope) pairs of the plugins of this repository: each one at
  user scope, and each one at project scope whose project is this repository."""
  pairs = []
  for entry in claude_json("plugin", "list", "--json"):
    if not isinstance(entry, dict) or entry.get("scope") not in ("user", "project"):
      continue
    plugin = text(entry.get("id"))
    scope = entry["scope"]
    if not plugin:
      continue
    if scope == "project":
      path = entry.get("projectPath")
      path = "" if path is None or path is False else text(path)
      path = path or "."
      if not os.path.isdir(path) or os.path.realpath(path) != root:
        continue
    pairs.append((plugin, scope))
  return pairs


def wanted(key):
  """The (plugin, source) pairs of the table key of .config/bootstrap/tools.toml."""
  value = helpers.bootstrap_get(key)["value"]
  value = {} if value is None or value is False else value
  return [(plugin, text(source)) for plugin, source in value.items()]


def main():
  root = os.environ["MISE_PROJECT_ROOT"]
  # A git submodule shares the Claude Code setup of its root repository: the
  # task does not apply there.
  superproject = subprocess.run(
    ["git", "-C", root, "rev-parse", "--show-superproject-working-tree"],
    stdout=subprocess.PIPE,
    stderr=subprocess.DEVNULL,
    text=True,
    check=False,
  )
  if superproject.returncode == 0 and superproject.stdout.rstrip("\n"):
    return 0

  helpers.print_header("Setting up the Claude Code plugins ...")

  if not helpers.has_tool("claude"):
    helpers.print_warn("claude is not on PATH — skipping AI setup.")
    helpers.print_yellow("Install it from https://claude.com/code, then run this task again.")
    return 0
  # The project scope is the working directory.
  os.chdir(root)
  root = os.path.realpath(".")

  failed = False

  # The installed plugins, read once, before any change.
  installed = set(plugins_here(root))

  # The plugins of [tools.claude.plugins.user] and [tools.claude.plugins.project]
  # in .config/bootstrap/tools.toml, with the entries that other tools
  # contribute: `"<plugin>@<marketplace>" = "<source>"`. A failed read of
  # `bootstrap config get`, for example with no catalog of bootstrap, stops the
  # task with the code of bootstrap_get.
  wanted_user = wanted("tools.claude.plugins.user")
  wanted_project = wanted("tools.claude.plugins.project")

  # The record of the project plugins that this task installed:
  # `tools.claude.plugins.installed`, a list of `<plugin>@<marketplace>`. A
  # plugin that is not in the record is never uninstalled.
  value = helpers.bootstrap_get("tools.claude.plugins.installed")["value"]
  record_before = [text(p) for p in ([] if value is None or value is False else value)]

  # A recorded plugin that is no longer installed at project scope leaves the
  # record.
  record = [p for p in record_before if p and (p, "project") in installed]

  def record_add(plugin):
    if plugin not in record:
      record.append(plugin)

  # Each listed plugin that is missing at its scope is installed. Its
  # marketplace is added first from <source>, at the same scope, when no scope
  # has it. Each listed project plugin that is installed, before or now, goes
  # in the record. present gets the (plugin, scope) pair of each listed plugin
  # that is installed.
  present = []
  listed = claude_json("plugin", "marketplace", "list", "--json")
  marketplaces = [text(m.get("name")) for m in listed if isinstance(m, dict)]
  for scope, plugins in (("user", wanted_user), ("project", wanted_project)):
    for plugin, source in plugins:
      if not plugin:
        continue
      if (plugin, scope) not in installed:
        marketplace = plugin.rpartition("@")[2]
        if marketplace not in marketplaces:
          if not claude_step(
            f"Adding the marketplace {marketplace} ({scope})",
            "plugin",
            "marketplace",
            "add",
            "--scope",
            scope,
            source,
          ):
            failed = True
          marketplaces.append(marketplace)
        if not claude_step(f"Installing {plugin} ({scope})", "plugin", "install", "--scope", scope, plugin):
          failed = True
          continue
      present.append((plugin, scope))
      if scope == "project":
        record_add(plugin)

  # A recorded plugin that is no longer in [tools.claude.plugins.project] is
  # uninstalled at project scope, with the dependencies that only it needed. A
  # failed uninstall keeps it in the record, so the next run tries again.
  listed_project = [plugin for plugin, _ in wanted_project]
  kept = []
  for plugin in record:
    if plugin in listed_project:
      kept.append(plugin)
      continue
    if not claude_step(
      f"Uninstalling {plugin} (project)", "plugin", "uninstall", "--scope", "project", "--prune", "-y", plugin
    ):
      kept.append(plugin)
      failed = True
  record = kept

  # With --upgrade, the marketplaces, then each listed plugin that is
  # installed, at its scope. claude has no command that updates all plugins.
  if os.environ.get("usage_upgrade", "false") == "true":
    if not claude_step("Updating the marketplaces", "plugin", "marketplace", "update"):
      failed = True
    for plugin, scope in present:
      if not claude_step(f"Updating {plugin} ({scope})", "plugin", "update", "--scope", scope, plugin):
        failed = True

  # The record is written only when it changed. A failed write is a failed
  # step: the next run corrects the record from the installed plugins.
  if record != record_before:
    binary = ["mise", "x", "--", "bootstrap"]
    if os.environ.get("BOOTSTRAP_BIN", ""):
      binary = [os.environ["BOOTSTRAP_BIN"]]
    plugins = json.dumps(record, ensure_ascii=False, separators=(",", ":"))
    helpers.print_wait("Recording the project plugins of setup:ai ... ")
    try:
      result = subprocess.run(
        [*binary, "config", "set", "tools.claude.plugins.installed", plugins],
        stdin=subprocess.DEVNULL,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.PIPE,
        text=True,
        errors="surrogateescape",
        check=False,
      )
      code, err = result.returncode, result.stderr
    except OSError as error:
      code, err = 127, str(error)
    if code == 0:
      helpers.print_success()
    else:
      helpers.print_error()
      print_errors(err.rstrip("\n"))
      failed = True

  if failed:
    helpers.print_error("Some Claude Code steps failed. The errors are above.")
    return 1
  return 0


if __name__ == "__main__":
  sys.exit(main())
